use super::*;
use crate::{retained_clone::RetainedCloneStep,retirement::controlled::ControlledRetirement};
#[derive(crate::RetireOwned)]
struct Row{rank:i64,label:String}
impl Clone for Row{fn clone(&self)->Self{panic!("original persistent construction must not clone row payloads")}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){crate::observe_retirement_allocations(run)}
fn account(p:RetainedCloneProgress,g:RetainedCloneGrant,h:(usize,usize),total:&mut(usize,usize)){assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));total.0+=h.0;total.1+=h.1;}
fn denied(d:RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{let g=grant(d);[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,g)|active.then_some(g))}
fn close_value<T:RetireOwned>(value:T,total:&mut(usize,usize))->usize{let(mut owner,h)=observe(||ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original builder output retirement")));total.0+=h.0;total.1+=h.1;let mut turns=0;while !owner.terminal_is_empty(){let d=owner.next_demand(4096).unwrap();let mut g=grant(d);g.maximum_copy_bytes=g.maximum_copy_bytes.max(4096);let(s,h)=observe(||owner.step(g).unwrap());account(s.progress(),g,h,total);turns+=1;}assert_eq!(observe(||drop(owner)).1,(0,0));turns}
fn close_builder(builder:&mut PersistentListBuilder<Row>,total:&mut(usize,usize))->usize{builder.begin_close();let mut turns=0;while !builder.terminal_is_empty(){let d=builder.close_demand(4096).unwrap();for g in denied(d){let(s,h)=observe(||builder.close_step(g).unwrap());assert_eq!(h,(0,0));assert_eq!(s.progress(),Default::default());}let mut g=grant(d);g.maximum_copy_bytes=g.maximum_copy_bytes.max(4096);let(s,h)=observe(||builder.close_step(g).unwrap());account(s.progress(),g,h,total);turns+=1;}turns}
fn advance(builder:&mut PersistentListBuilder<Row>,total:&mut(usize,usize)){let d=builder.demand().unwrap();for g in denied(d){let(s,h)=observe(||builder.advance(g).unwrap());assert_eq!(h,(0,0));assert_eq!(s.progress(),Default::default());}let g=grant(d);let(s,h)=observe(||builder.advance(g).unwrap());account(s.progress(),g,h,total);}

/// 📥️ Original row streams form fixed persistent pages with exact paid carries and physical cancellation.
#[test]
fn persistent_owned_builder_preserves_ranked_originals_and_every_receiving_frontier(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let prefix=fixture["prefix"].as_str().unwrap();let stride=fixture["stride"].as_i64().unwrap();
 for case in fixture["cases"].as_array().unwrap(){let count=case["length"].as_u64().unwrap()as usize;for cut in std::iter::once(None).chain(fixture["cuts"].as_array().unwrap().iter().map(|c|Some(c.as_u64().unwrap()as usize))){
  let mut total=(0,0);let d=PersistentListBuilder::<Row>::constructor_demand();for g in denied(d){let(result,h)=observe(||PersistentListBuilder::<Row>::new(count,g).unwrap());assert!(result.is_none());assert_eq!(h,(0,0));}let(mut builder,h)=observe(||PersistentListBuilder::<Row>::new(count,grant(d)).unwrap().unwrap());assert_eq!(h,(0,0));let mut pointers=Vec::new();let supplied=cut.unwrap_or(count).min(count);
  for index in 0..supplied{let(mut row,h)=observe(||{let value=Row{rank:index as i64*stride,label:if index==0{prefix.repeat(10923)}else{format!("{prefix}{index}")}};let g=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:SealedShared::<Row>::birth_bytes(),maximum_depth:1,..Default::default()};Some(SealedShared::admit(value,SharedIssuer::owned(),g).unwrap_or_else(|_|panic!("original builder row issuer")).0)});total.0+=h.0;total.1+=h.1;pointers.push((row.as_ref().unwrap().get()as*const Row,row.as_ref().unwrap().get().label.as_ptr()));let d=builder.adopt_demand().unwrap();for g in denied(d){let(result,h)=observe(||builder.adopt(&mut row,g).unwrap());assert!(result.is_none());assert!(row.is_some());assert_eq!(h,(0,0));}let g=grant(d);let(p,h)=observe(||builder.adopt(&mut row,g).unwrap().unwrap());account(p,g,h,&mut total);assert!(row.is_none());while !builder.accepts_row(){advance(&mut builder,&mut total);}}
  let mut output=None;if cut.is_none(){let d=builder.finish_demand().unwrap();for g in denied(d){let(result,h)=observe(||builder.finish(g).unwrap());assert!(result.is_none());assert_eq!(h,(0,0));}let g=grant(d);let(p,h)=observe(||builder.finish(g).unwrap().unwrap());account(p,g,h,&mut total);while !builder.output_ready(){advance(&mut builder,&mut total);}let d=builder.take_demand().unwrap();for g in denied(d){let(result,h)=observe(||builder.take(g).unwrap());assert!(result.is_none());assert_eq!(h,(0,0));}let g=grant(d);let((root,p),h)=observe(||builder.take(g).unwrap().unwrap());account(p,g,h,&mut total);assert_eq!(root.len(),count);assert_eq!(root.root.as_ref().map(|_|u64::from(root.height)),case["height"].as_u64());let actual:Vec<_>=(0..count).map(|i|root.get(i).unwrap().rank).collect();let expected:Vec<_>=(0..count).map(|i|i as i64*stride).collect();assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(expected).unwrap());for(index,(row,text))in pointers.iter().enumerate(){let original=root.get(index).unwrap();assert_eq!(original as*const Row,*row);assert_eq!(original.label.as_ptr(),*text);}output=Some(root);}
  let mut closed=close_builder(&mut builder,&mut total);assert_eq!(observe(||drop(builder)).1,(0,0));if let Some(root)=output{closed+=close_value(root,&mut total);}assert_eq!(total.0,total.1);eprintln!("[DEBUG] original persistent owned builder rows={count} cut={cut:?} exactHeight={} originalRowPointers=true rowClone=0 temporaryFullVector=0 physicalBirth={} physicalRelease={} closeTurns={closed} deniedAxes=5 terminalDrop=0",case["height"],total.0,total.1);
 }}
}

/// 🚧️ Refused missing or excess rows remain in their genuine original owned receiving slots.
#[test]
fn persistent_owned_builder_refuses_missing_and_excess_without_consuming_input(){
 let mut total=(0,0);let mut missing=PersistentListBuilder::<Row>::new(1,grant(PersistentListBuilder::<Row>::constructor_demand())).unwrap().unwrap();assert!(missing.finish_demand().is_err());close_builder(&mut missing,&mut total);assert_eq!(observe(||drop(missing)).1,(0,0));
 let mut excess=PersistentListBuilder::<Row>::new(0,grant(PersistentListBuilder::<Row>::constructor_demand())).unwrap().unwrap();let(mut row,h)=observe(||{let g=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:SealedShared::<Row>::birth_bytes(),maximum_depth:1,..Default::default()};Some(SealedShared::admit(Row{rank:9,label:"α🙂".into()},SharedIssuer::owned(),g).unwrap_or_else(|_|panic!("original excess row")).0)});total.0+=h.0;let pointer=row.as_ref().unwrap().get()as*const Row;assert!(excess.adopt_demand().is_err());assert_eq!(row.as_ref().unwrap().get()as*const Row,pointer);close_builder(&mut excess,&mut total);assert_eq!(observe(||drop(excess)).1,(0,0));close_value(row.take().unwrap(),&mut total);assert_eq!(total.0,total.1);eprintln!("[DEBUG] original persistent missing/excess refusal preserves input pointer, physicalBirth={} physicalRelease={} terminalDrop=0",total.0,total.1);
}

/// 🛑️ Every real page birth, carry, partial branch and final owned root keeps its funded cancel custody.
#[test]
fn persistent_owned_builder_cancels_every_preparation_action_frontier(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let count=fixture["preparation"]["length"].as_u64().unwrap()as usize;let mut phases=std::collections::BTreeSet::new();let mut finished_roots=0;
 for cut in fixture["preparation"]["cuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let mut total=(0,0);let mut builder=PersistentListBuilder::<Row>::new(count,grant(PersistentListBuilder::<Row>::constructor_demand())).unwrap().unwrap();let mut supplied=0;let mut finished=false;
  for _ in 0..cut{if builder.output_ready(){finished_roots+=1;break;}if builder.accepts_row()&&supplied<count{let(mut row,h)=observe(||{let value=Row{rank:supplied as i64*2,label:format!("α🙂{supplied}")};let g=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:SealedShared::<Row>::birth_bytes(),maximum_depth:1,..Default::default()};Some(SealedShared::admit(value,SharedIssuer::owned(),g).unwrap_or_else(|_|panic!("original cancellation row")).0)});total.0+=h.0;total.1+=h.1;let g=grant(builder.adopt_demand().unwrap());let(p,h)=observe(||builder.adopt(&mut row,g).unwrap().unwrap());account(p,g,h,&mut total);supplied+=1;phases.insert("adopt");}else if builder.accepts_row()&&!finished{let g=grant(builder.finish_demand().unwrap());let(p,h)=observe(||builder.finish(g).unwrap().unwrap());account(p,g,h,&mut total);finished=true;phases.insert("finish");}else{let d=builder.demand().unwrap();phases.insert(if d.capacity_bytes>0{"page-birth"}else{"carry-scan"});advance(&mut builder,&mut total);}}
  close_builder(&mut builder,&mut total);assert_eq!(observe(||drop(builder)).1,(0,0));assert_eq!(total.0,total.1);
 }
 assert_eq!(phases.into_iter().collect::<Vec<_>>(),["adopt","carry-scan","finish","page-birth"]);assert!(finished_roots>0);eprintln!("[DEBUG] original persistent all{} action cuts include final ready roots={finished_roots}, all leaf/branch page births and carries; physicalBirth=physicalRelease, deniedAxes=5, terminalDrop=0",fixture["preparation"]["cuts"].as_array().unwrap().len());
}

/// 🎮️ A normal bounded interaction turn can begin original persistent construction without a giant header exception.
#[test]
fn persistent_owned_builder_constructor_fits_authored_interaction_quantum(){let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let maximum=f["interactionQuantum"]["copyBytes"].as_u64().unwrap()as usize;let d=PersistentListBuilder::<Row>::constructor_demand();assert!(d.copy_bytes<=maximum,"original persistent builder constructor requires{} copied bytes, authored responsive quantum is{maximum}",d.copy_bytes);let mut builder=PersistentListBuilder::<Row>::new(65537,grant(d)).unwrap().unwrap();let mut total=(0,0);close_builder(&mut builder,&mut total);assert_eq!(observe(||drop(builder)).1,(0,0));eprintln!("[DEBUG] original persistent owned constructor copyBytes={} <= responsiveQuantum={maximum}, heapBirth=0, terminalDrop=0",d.copy_bytes);}
